+                <div class="card-body py-2">
+                    <div class="fw-bold">Total</div>
+                    <div class="fs-5">@_allTasks.Count</div>
+                </div>
+            </div>
+        </div>
+        @foreach (var col in _columns)
+        {
+            <div class="col">
+                <div class="card text-center">
+                    <div class="card-body py-2">
+                        <div class="fw-bold">@col</div>
+                        <div class="fs-5">@GetTasksForColumn(col).Count</div>
+                    </div>
+                </div>
+            </div>
+        }
+        <div class="col">
+            <div class="card text-center border-danger">
+                <div class="card-body py-2">
+                    <div class="fw-bold text-danger">Overdue</div>
+                    <div class="fs-5 text-danger">@_allTasks.Count(t => t.DueDate < DateTime.Today)</div>
+                </div>
+            </div>
+        </div>
+    </div>
+
+    <!-- Search Bar -->
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title..."
+               @bind="_searchQuery" @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban Columns -->
+    <div class="row g-3">
+        @for (var i = 0; i < _columns.Length; i++)
+        {
+            var colIndex = i;
+            var colName = _columns[colIndex];
+            var tasks = GetFilteredTasksForColumn(colName);
+
+            <div class="col-md-4">
+                <div class="card h-100">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <strong>@colName</strong>
+                        <span class="badge bg-secondary">@tasks.Count</span>
+                    </div>
+                    <div class="card-body d-flex flex-column gap-2" style="min-height: 200px;">
+                        @foreach (var task in tasks)
+                        {
+                            <div class="card shadow-sm">
+                                <div class="card-body p-2">
+                                    <div class="fw-semibold mb-1">@task.Title</div>
+                                    <div class="small text-muted mb-1">@task.Assignee</div>
+                                    <div class="d-flex justify-content-between align-items-center mb-1">
+                                        <span class="badge @GetPriorityBadgeClass(task.Priority)">@task.Priority</span>
+                                        <span class="small text-muted">@task.DueDate.ToString("MMM dd")</span>
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        @if (colIndex > 0)
+                                        {
+                                            var leftStatus = _columns[colIndex - 1];
+                                            <button class="btn btn-outline-secondary btn-sm flex-fill"
+                                                    @onclick="() => MoveTaskAsync(task.Id, leftStatus)">
+                                                &larr; Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < _columns.Length - 1)
+                                        {
+                                            var rightStatus = _columns[colIndex + 1];
+                                            <button class="btn btn-outline-secondary btn-sm flex-fill"
+                                                    @onclick="() => MoveTaskAsync(task.Id, rightStatus)">
+                                                Move Right &rarr;
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        <!-- Add Task Form -->
+                        @if (_addingToColumn == colName)
+                        {
+                            <div class="card border-primary mt-auto">
+                                <div class="card-body p-2">
+                                    <input type="text" class="form-control form-control-sm mb-1"
+                                           placeholder="Title" @bind="_newTitle" />
+                                    <input type="text" class="form-control form-control-sm mb-1"
+                                           placeholder="Assignee" @bind="_newAssignee" />
+                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                        <option value="High">High</option>
+                                        <option value="Medium">Medium</option>
+                                        <option value="Low">Low</option>
+                                    </select>
+                                    <input type="date" class="form-control form-control-sm mb-2"
+                                           @bind="_newDueDate" />
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-primary btn-sm flex-fill"
+                                                @onclick="() => SaveNewTaskAsync(colName)"
+                                                disabled="@_saving">
+                                            Save
+                                        </button>
+                                        <button class="btn btn-outline-secondary btn-sm flex-fill"
+                                                @onclick="CancelAdd">
+                                            Cancel
+                                        </button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                        else
+                        {
+                            <button class="btn btn-outline-primary btn-sm mt-auto"
+                                    @onclick="() => StartAdd(colName)">
+                                + Add Task
+                            </button>
+                        }
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private string? _errorMessage;
+    private string _searchQuery = string.Empty;
+
+    // Add-task form state
+    private string? _addingToColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+    private bool _saving;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetTasksForColumn(string status) =>
+        _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredTasksForColumn(string status) =>
+        _allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(_searchQuery) ||
+                         t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private static string GetPriorityBadgeClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                var old = _allTasks[idx];
+                _allTasks[idx] = old with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        _addingToColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingToColumn = null;
+
+    private async Task SaveNewTaskAsync(string column)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        _saving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
+            // If the service doesn't set the status to the current column, adjust it
+            if (created.Status != column)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, column);
+                created = created with { Status = column };
+            }
+            _allTasks.Add(created);
+            _addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

